+            log.warn(
+                    "candidate rejected on admission: paramSearchId={} candidateNo={} code={} message={}",
+                    candidate.getParamSearchId(),
+                    candidate.getCandidateNo(),
+                    rejected.getErrorCode(),
+                    rejected.getMessage());
+            candidateRepository.update(
+                    candidate.markExcluded(
